// Min-heap genérico (armazena índices de objetos, com função de comparação)
function makeHeap(cmp) {
  const a = [];
  return {
    size: () => a.length,
    push(x) {
      a.push(x);
      let i = a.length - 1;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (cmp(a[i], a[p]) < 0) {
          const tmp = a[i]; a[i] = a[p]; a[p] = tmp;
          i = p;
        } else break;
      }
    },
    pop() {
      if (a.length === 0) return -1;
      const top = a[0];
      const last = a.pop();
      if (a.length > 0) {
        a[0] = last;
        let i = 0;
        for (;;) {
          const l = 2 * i + 1, r = l + 1;
          let m = i;
          if (l < a.length && cmp(a[l], a[m]) < 0) m = l;
          if (r < a.length && cmp(a[r], a[m]) < 0) m = r;
          if (m === i) break;
          const tmp = a[i]; a[i] = a[m]; a[m] = tmp;
          i = m;
        }
      }
      return top;
    }
  };
}

// Heap por tipo: mínimo preço
